    <script>
      const lines = ["#logo", ".headline-line", "#ministry", "#title"];

      gsap.set(lines, { autoAlpha: 0, y: 24 });
      gsap.set("#signature-rule", { scaleY: 0 });
      gsap.set("#right-column", { xPercent: 100 });

      const tl = gsap.timeline({ defaults: { ease: "power3.out" } });

      // 1. The dark panel arrives first and sets the frame.
      tl.to("#right-column", { xPercent: 0, duration: 1.1, ease: "power3.inOut" }, 0);

      // 2. Content rises along the same flow line, top to bottom.
      tl.to("#logo",          { autoAlpha: 1, y: 0, duration: 0.8 }, 0.35);
      tl.to(".headline-line", { autoAlpha: 1, y: 0, duration: 0.9, stagger: 0.1 }, 0.55);

